import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"Operating site-only keys safely","description":"","frontmatter":{},"headers":[],"relativePath":"en/operations/jev-keys.md","filePath":"en/operations/jev-keys.md","lastUpdated":1794405696000}`),a={name:`en/operations/jev-keys.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="operating-site-only-keys-safely" tabindex="-1">Operating site-only keys safely <a class="header-anchor" href="#operating-site-only-keys-safely" aria-label="Permalink to “Operating site-only keys safely”">​</a></h1><p>These are steps for the people who operate the environment. Site admins use <a href="./../guides/jev">Jev connection in the admin console</a>. The <strong>encryption key</strong> you create here is different from the <strong>API key</strong> issued by Jev.</p><h2 id="how-it-is-stored" tabindex="-1">How it is stored <a class="header-anchor" href="#how-it-is-stored" aria-label="Permalink to “How it is stored”">​</a></h2><p>API keys are encrypted with AES-256-GCM and saved in a dedicated table. The encryption key isn&#39;t put in the database. It is held in a Cloudflare runtime secret or Node.js&#39;s secrets mechanism. The ciphertext is verified against the site ID and the update version, so it can&#39;t be copied to another site and used there.</p><p>This protects the values from someone who can only read the database. It doesn&#39;t isolate them from an operator who controls both the app process and the encryption key. The admin console shows only whether a key is set, and there is no API that reveals a key.</p><h2 id="generate-the-encryption-key-first-time-only" tabindex="-1">Generate the encryption key (first time only) <a class="header-anchor" href="#generate-the-encryption-key-first-time-only" aria-label="Permalink to “Generate the encryption key (first time only)”">​</a></h2><p>In an environment where JEV_KEYRING is already set, don&#39;t overwrite it with a new value. If you lose it, saved API keys can no longer be decrypted. Use separate encryption keys for Preview and Production.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jev:keyring:create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/preview-jev-keyring.json</span></span></code></pre></div><p>This creates a JSON file containing the encryption key with permission 0600. The value isn&#39;t printed to the terminal, and an existing file isn&#39;t overwritten. <code>data/</code> is excluded from Git. Don&#39;t add the file to Git, chat or published artifacts. On Windows or another file system, also check the ACLs.</p><h2 id="cloudflare-preview" tabindex="-1">Cloudflare Preview <a class="header-anchor" href="#cloudflare-preview" aria-label="Permalink to “Cloudflare Preview”">​</a></h2><p>First check only the setting names, and if JEV_KEYRING already exists, keep using it.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR-PREVIEW-NAME</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>Only if it isn&#39;t set, pass the newly generated JSON for Preview through standard input.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> JEV_KEYRING</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR-PREVIEW-NAME</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/preview-jev-keyring.json</span></span></code></pre></div><p>Don&#39;t put it in ordinary vars, build variables or the shared Previews base. This project doesn&#39;t inherit the base. Preview&#39;s own secrets are kept in the next deployment too. Then do the <a href="./../getting-started/preview-production">Preview deployment</a>, and confirm that the encryption setup notice disappears from &quot;Jev connection&quot; in the admin console.</p><h2 id="cloudflare-production" tabindex="-1">Cloudflare Production <a class="header-anchor" href="#cloudflare-production" aria-label="Permalink to “Cloudflare Production”">​</a></h2><p><strong>After the production update is approved</strong>, check the setting names, and only if it isn&#39;t set, generate and register a separate file.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jev:keyring:create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/production-jev-keyring.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> JEV_KEYRING</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/production-jev-keyring.json</span></span></code></pre></div><p>The generation and registration above are for the first time. If an existing JEV_KEYRING is present, don&#39;t run them, and use the key rotation steps instead. Changing a secret is itself an update of the runtime environment. Don&#39;t do it on Production before checking.</p><p>A Production deployment needs ADMIN_TOKEN and JEV_KEYRING. Register the API key issued by Jev in each site&#39;s &quot;Jev connection&quot;. The environment&#39;s JEV_API_KEY is not used. There is also no process that copies a shared key to each site automatically. A site that ran on a shared key holds its Jev-based judgments until its own key is registered.</p><h2 id="node-js" tabindex="-1">Node.js <a class="header-anchor" href="#node-js" aria-label="Permalink to “Node.js”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jev:keyring:create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/node-jev-keyring.json</span></span></code></pre></div><p>Set the absolute path of that file in the runtime environment&#39;s <code>JEV_KEYRING_FILE</code>, and make it readable only by the user running Node.js. Persist it, restrict access separately from the database, and back it up. You can also pass the JSON from a secrets management service as the runtime <code>JEV_KEYRING</code>. If both are set, JEV_KEYRING takes precedence.</p><p><code>npm run review</code> automatically generates <code>.jev-keyring.json</code> next to the review database the first time and reuses it. Because judgment is fixed, saving an API key doesn&#39;t send anything to the real Jev.</p><h2 id="backups-and-key-rotation" tabindex="-1">Backups and key rotation <a class="header-anchor" href="#backups-and-key-rotation" aria-label="Permalink to “Backups and key rotation”">​</a></h2><p>A database backup alone can&#39;t restore API keys. Back up the matching encryption key separately in a secrets management service, and limit who can read it. Don&#39;t rely on being able to read a Cloudflare secret&#39;s value back later.</p><ol><li>In a safe environment, generate a new 32-byte random value and add it to <code>keys</code> in the existing JSON under a new generation name. Keep the old generation&#39;s value.</li><li>Change <code>active</code> to the new generation and update JEV_KEYRING. Don&#39;t delete the old generation yet.</li><li>On each site, keep &quot;Site-only key&quot; selected and save with the API key field empty. This re-encrypts the current value with the new generation.</li><li>After confirming every site has been migrated and the backup recovery policy, delete old generations you no longer need. Keep any keys needed for past backups safely, separately.</li></ol><p>The JSON has <code>active</code> and <code>keys</code>. Each key is 32 bytes in base64url (without the trailing <code>=</code>), a generation name is up to 40 characters of letters, digits, underscores and hyphens, and there can be up to 10 generations. This is independent of updating AUTH_SECRET.</p><h2 id="leaks-loss-and-rollback" tabindex="-1">Leaks, loss and rollback <a class="header-anchor" href="#leaks-loss-and-rollback" aria-label="Permalink to “Leaks, loss and rollback”">​</a></h2><p>If an API key is suspected, reissue or revoke it on the Jev side and replace it from the site&#39;s &quot;Jev connection&quot;. Deleting it in the app alone does not revoke the provider&#39;s key.</p><p>If the encryption key leaks, also check access to the database, and if necessary revoke and reissue all stored sites&#39; API keys with the provider. Simply updating the encryption key can&#39;t invalidate old ciphertext that has already leaked.</p><p>If you lose the encryption key, restore from the matching backup, or register a new encryption key and each site&#39;s API key again. It never switches to a shared key automatically to keep processing.</p><p>After setting site-only keys or a usage stop, rolling back to only old code that predates this support could call with a shared key. Prioritize deploying a fix on a version that supports it, and if a rollback is needed, consider the code, database and encryption key together at the same recovery point.</p>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};